public class MeioTransporte { protected int capacidade; protected double velocidadeMaxima; public MeioTransporte(int capacidade,double velocidadeMaxima){this.capacidade=capacidade;this.velocidadeMaxima=velocidadeMaxima;} public void exibirInfo(){System.out.println("Capacidade: "+capacidade+", velocidade: "+velocidadeMaxima);} public void mover(double distancia){System.out.println("Percorrendo "+distancia+" km");} }
